-- expires_on is a 'YYYY-MM-DD' string or NULL (no expiry).
ALTER TABLE payments ADD COLUMN expires_on TEXT;

args.new_string:
def register_advance(self, company_id, amount, operator="WEB", doc_no=None, expires_on=None):
    if not company_id:
        raise ValueError("No customer specified.")
    amount = float(amount or 0)
    if amount <= 0:
        raise ValueError("The advance amount must be > 0.")
    if expires_on is not None:
        try:
            exp = datetime.datetime.strptime(str(expires_on), "%Y-%m-%d").date()
        except (ValueError, TypeError):
            raise ValueError("Invalid expiry date: expected a real YYYY-MM-DD date.")
        if exp < datetime.date.today():
            raise ValueError("Invalid expiry date: it is before today.")
        expires_on = exp.strftime("%Y-%m-%d")
    with self._lock:
        cur = self.cursor()
        cur.execute(
            "INSERT INTO payments (company_id, date, type, amount, remaining, doc_no, "
            "operator_id, created_at, expires_on) VALUES (?,?, 'advance', ?,?,?,?,?,?)",
            (company_id, datetime.date.today().strftime("%Y-%m-%d"), amount, amount, doc_no,
             operator, datetime.datetime.now().isoformat(timespec="seconds"), expires_on))
        self.conn.commit()
        return cur.lastrowid

